//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF06003.xml";
scwin.pLIST_PROMT_SEQ = "";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜
scwin.fn_SetPar;
scwin.gIntviewOrder;
scwin.MGS_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.trsIdx = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/**	
 * 요약재무자료(YYYY-2,YYYY-1,YYYY) 세팅
 **/
scwin.fn_init = function() {
    var parentWin = $c.frame.path("../");
    scwin.pLIST_PROMT_SEQ = parentWin.scwin.pLIST_PROMT_SEQ;
    scwin.fn_log(scwin.pLIST_PROMT_SEQ);
    if (scwin.pLIST_PROMT_SEQ == undefined) {
        scwin.pLIST_PROMT_SEQ = "";
    }
    var YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    var YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    var YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    var YY = scwin.vCurDate.substr(0, 4);
    var YY1 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(1, 10);
    var YY2 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(2, 10);
    var YY3 = parseInt(scwin.vCurDate.substring(0, 4), 10) + parseInt(3, 10);
    var strCbd_SME_YN = YY_1 + "^" + YY_1 + "," + YY + "^" + YY + "," + YY1 + "^" + YY1 + "," + YY2 + "^" + YY2 + "," + YY3 + "^" + YY3 + ",9999^ 미정"; //	상장예정시기 setting(당해년도,Y+1,Y+2,Y+3,미정)		
    cmb_LIST_SCHDL_TM_1.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_2.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_3.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_4.CBData = strCbd_SME_YN;
    cmb_LIST_SCHDL_TM_5.CBData = strCbd_SME_YN;
    $c.stf.setObjectValue(txb_YY3, YY_3 + "년"); //	요약재무자료 Title(Y-2)
    $c.stf.setObjectValue(txb_YY2, YY_2 + "년"); //	요약재무자료 Title(Y-1)
    $c.stf.setObjectValue(txb_YY1, YY_1 + "년"); //	요약재무자료 Title(Y)		
    $c.stf.showObj(panel_Item, true);
};


/**
 *	공통코드
 **/
scwin.fn_searchCode = function() {
    var curYY = parseInt(scwin.vCurDate.substr(0, 4));
    var strCodeCnt = "^ ,";
    for (i = 0; i < 10; i++) {
        strCodeCnt += curYY + "^" + curYY + ",";
        curYY = curYY - 1;
    }
    gcurYY = curYY;
    cmb_CEO_CRS_STRT_DD.CBData = strCodeCnt;
    cmb_LIST_PROFS_CRS_STRT_DD.CBData = strCodeCnt;
    /*
    	03270	면담방법코드(1:방문,2:유선,3:서면,4:기타)
    	*/
    var arrCid = [{
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_1"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_2"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_3"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_4"
    }, {
        cid: "INTVIEW_ACTIV_CD",
        cnm: "cmb_INTVIEW_METHD_CD_5"
    }, {
        cid: "LIST_PROPEL_STEP_TP_CD",
        cnm: "cmb_LIST_PROPEL_STEP_TP_CD"
    }, {
        cid: "VENT_ADM_INST_CD",
        cnm: "cmb_REL_INST_NM"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','INTVIEW_ACTIV_CD','LIST_PROPEL_STEP_TP_CD','VENT_ADM_INST_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "^' '";
        for (j = 1; j <= dts_Code.getTotalRow(); j++) {
            if (dts_Code.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Code.getCellData(j, "VALUE") + "^" + dts_Code.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }

    // 담당자
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listInvstgEmpKoList";
    dts_EmpNo.DataID = encodeURI(url);
    dts_EmpNo.Reset();
    strCbd = "";
    if (dts_EmpNo.getTotalRow() > 0) {
        strCbd = "^선택";
        for (var i = 1; i <= dts_EmpNo.getTotalRow(); i++) {
            strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }

        // 1차
        cmb_INTVIEW_CHRG_EMP_NO_10.CBData = strCbd; //	KRX 담당자
        cmb_INTVIEW_CHRG_EMP_NO_11.CBData = strCbd; //	KRX 담당자2
        cmb_INTVIEW_CHRG_EMP_NO_12.CBData = strCbd; //	KRX 담당자3	

        // 2차
        cmb_INTVIEW_CHRG_EMP_NO_20.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_21.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_22.CBData = strCbd;

        // 3차
        cmb_INTVIEW_CHRG_EMP_NO_30.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_31.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_32.CBData = strCbd;

        // 4차
        cmb_INTVIEW_CHRG_EMP_NO_40.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_41.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_42.CBData = strCbd;

        // 5차
        cmb_INTVIEW_CHRG_EMP_NO_50.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_51.CBData = strCbd;
        cmb_INTVIEW_CHRG_EMP_NO_52.CBData = strCbd;
    }

    //	주관사명
    dts_MajagntInst.DataID = "/CodeAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listLeadCom&For=''";
    dts_MajagntInst.Reset();
    for (var k = 1; k <= dts_MajagntInst.getTotalRow(); k++) {
        if (dts_MajagntInst.getCellData(k, "TEXT") == "") {
            //널값은 삭제
            $c.cp.removeRow(dts_MajagntInst, k);
        }
    }
};




/**
 * 우편번호
 **/
scwin.fn_SetParZipCd = function(arrPar) {
    txb_LOC_ZIPCD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_LOC_ADDR.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
scwin.fn_listGenenal = function() {
    //	상장유치면담이력 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtIntviewHistKoList";
    url += "&inputMessageId=LISTPRMTINTIWHISTKO_INOUT&outputMessageId=LISTPRMTINTIWHISTKO_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};


/**
 *	조회
 **/
scwin.fn_list_sync = function() {
    //	상장유치면담이력 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtIntviewHistKoList";
    url += "&inputMessageId=LISTPRMTINTIWHISTKO_INOUT&outputMessageId=LISTPRMTINTIWHISTKO_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();

    //	파일첨부
    if (scwin.pLIST_PROMT_SEQ == "") {
        dts_fileList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LIST_PRMT_INTIW_ATTACH_INOUT";
        dts_fileList.Reset();
    } else {
        trs_Read.Action = "/ListPromtHistMgt.do?method=listPromtIntviewAttachFile" + "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        trs_Read.KeyValue = "JSP(O:pOutput=dts_fileList)";
        trs_Read.Post();
    }

    //	요약재무자료 조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtFncKoList";
    url += "&inputMessageId=LISTPROMTFNCKOLIST_INOUT&outputMessageId=LISTPROMTFNCKOLIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_YearFnc.DataID = encodeURI(url);
    dts_YearFnc.Reset();

    // 투자이력
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtInvstKo";
    url += "&inputMessageId=LISTPRMT_INVST_KO_INOUT&outputMessageId=LISTPRMT_INVST_KO_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_Invst.DataID = encodeURI(url);
    dts_Invst.Reset();

    //면담개요조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtIntviewDtl";
    url += "&inputMessageId=LISTPROMTINTVIEWDTL_INOUT&outputMessageId=LISTPROMTINTVIEWDTL_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_IntviewDtlList.DataID = encodeURI(url);
    dts_IntviewDtlList.Reset();

    //면담대상자조회
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtIntviewPrnKo";
    url += "&inputMessageId=LISTPROMTINTVIEWPRNKO_INOUT&outputMessageId=LISTPROMTINTVIEWPRNKO_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_IntviewPrnList.DataID = encodeURI(url);
    dts_IntviewPrnList.Reset();

    //	요약재무자료 전체조회(엑셀연동)
    var url = "/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listPromtFncTotalList";
    url += "&inputMessageId=LISTPROMTFNCTOTALLIST_INOUT&outputMessageId=LISTPROMTFNCTOTALLIST_INOUT";
    url += "&LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    dts_YearFncTotal.DataID = encodeURI(url);
    dts_YearFncTotal.Reset();
    scwin.fn_setHeader();
    if (dts_List.getTotalRow() < 1) {
        dts_List.insertRow();
    }
    if (dts_IntviewPrnList.getTotalRow() < 1) {
        dts_IntviewPrnList.insertRow();
    }
    if (dts_IntviewDtlList.getTotalRow() < 1) {
        dts_IntviewDtlList.insertRow();
    } else {
        if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_5") != '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_5"))) {
            MaxTab_01.setSelectedTabIndex(5);
        } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4") != '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4"))) {
            MaxTab_01.setSelectedTabIndex(4);
        } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_3") != '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_3"))) {
            MaxTab_01.setSelectedTabIndex(3);
        } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_2") != '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_2"))) {
            MaxTab_01.setSelectedTabIndex(2);
        } else {
            MaxTab_01.setSelectedTabIndex(1);
        }
    }
    if ($c.stf.getObjectValue(cmb_INTVIEW_METHD_CD_1) == "4") {
        // 면담방법이 기타일경우
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_1, true);
    } else {
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_1, false);
    }
    if ($c.stf.getObjectValue(cmb_INTVIEW_METHD_CD_2) == "4") {
        // 면담방법이 기타일경우
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_2, true);
    } else {
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_2, false);
    }
    if ($c.stf.getObjectValue(cmb_INTVIEW_METHD_CD_3) == "4") {
        // 면담방법이 기타일경우
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_3, true);
    } else {
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_3, false);
    }
    if ($c.stf.getObjectValue(cmb_INTVIEW_METHD_CD_4) == "4") {
        // 면담방법이 기타일경우
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_4, true);
    } else {
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_4, false);
    }
    if ($c.stf.getObjectValue(cmb_INTVIEW_METHD_CD_5) == "4") {
        // 면담방법이 기타일경우
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_5, true);
    } else {
        $c.stf.showObj(txb_INTVIEW_METHD_MISC_CONTN_5, false);
    }
};



/**
 * 입력값 Check
 **/
scwin.fn_checkForm = function() {
    if (!$c.cp.isModified(dts_List) && !$c.cp.isModified(dts_IntviewDtlList) &&
        !$c.cp.isModified(dts_IntviewPrnList) && !$c.cp.isModified(dts_YearFnc) &&
        !$c.cp.isModified(dts_YearFncTotal) && !$c.cp.isModified(dts_fileList) &&
        !$c.cp.isModified(dts_Invst)) {
        $c.win.alert(scwin.MGS_NO_UPDT);
        return false;
    }
    if ($c.stf.getObjectValue(txb_COM_NM) == "") {
        $c.win.alert("[회사명]을  입력하세요.");
        txb_COM_NM.focus();
        return false;
    }
    if (dts_List.getCellData(1, "CORP_REG_NO") == "") {
        $c.win.alert("[법인등록번호]을  입력하세요.");
        txb_CORP_REG_NO.focus();
        return false;
    }
    if (dts_List.getCellData(1, "CORP_REG_NO").length != 13) {
        $c.win.alert("[법인등록번호] 13자리가 아닙니다.");
        txb_CORP_REG_NO.focus();
        return false;
    }

    /*if(getObjectValue(txb_LOC_ADDR) == "") {
    	alert("[소재지을  입력하세요.");
    	txb_LOC_ADDR.focus();
    	return false;
    }*/

    return true;
};



/**
 * dts_YearFncChange 의 setHeader
 **/
scwin.fn_setHeader = function() {
    /* 재무정보 */
    /* 헤더정보:LIST_PROMT_SEQ,	BAS_YY,	SALES,	BZ_PROFT_AMT,	NETINCM_AMT */
    dts_YearFncChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=YEARFNCCHGKO_INOUT";
    dts_YearFncChange.reset();

    /* 상장촉진면담 대상자 */
    dts_IntviewPrnChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INTVIEWCHGKO_INOUT";
    dts_IntviewPrnChange.reset();

    /* 상장촉진면담 상세 */
    dts_IntviewDtlChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INTVIEWDTLCHGKO_INOUT";
    dts_IntviewDtlChange.reset();

    /* 투자 이력 */
    dts_InvstChange.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTPRMT_INVST_KO_INOUT";
    dts_InvstChange.reset();
};


/**
 * dts_YearFnc Dateset -> dts_YearFncChange로 변경
 **/
scwin.fn_setYearFncDataSet = function() {
    dts_YearFncChange.removeAll();

    //if(	dts_YearFnc.NameValue(1,"SALES_2") != "" || dts_YearFnc.NameValue(1,"BZ_PROFT_AMT_2") != "" || dts_YearFnc.NameValue(1,"NETINCM_AMT_2") != "" ||
    //	dts_YearFnc.NameValue(1,"ASST_TOTAMT_2") != "" || dts_YearFnc.NameValue(1,"DEBT_TOTAMT_2") != "" || dts_YearFnc.NameValue(1,"CAP_TOTAMT_2") != "" ) {
    dts_YearFncChange.insertRow();
    dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BAS_YY", $c.stf.getObjectValue(txb_YY3).substr(0, 4));
    if (dts_YearFnc.getCellData(1, "SALES_2") != "") {
        dts_YearFncChange.setCellData(1, "SALES", dts_YearFnc.getCellData(1, "SALES_2"));
    }
    if (dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_2") != "") {
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "BZ_PROFT_AMT", dts_YearFnc.getCellData(1, "BZ_PROFT_AMT_2"));
    }
    if (dts_YearFnc.getCellData(1, "NETINCM_AMT_2") != "") {
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "NETINCM_AMT", dts_YearFnc.getCellData(1, "NETINCM_AMT_2"));
    }
    if (dts_YearFnc.getCellData(1, "ASST_TOTAMT_2") != "") {
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "ASST_TOTAMT", dts_YearFnc.getCellData(1, "ASST_TOTAMT_2"));
    }
    if (dts_YearFnc.getCellData(1, "DEBT_TOTAMT_2") != "") {
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "DEBT_TOTAMT", dts_YearFnc.getCellData(1, "DEBT_TOTAMT_2"));
    }
    if (dts_YearFnc.getCellData(1, "CAP_TOTAMT_2") != "") {
        dts_YearFncChange.setCellData(dts_YearFncChange.getRowPosition(), "CAP_TOTAMT", dts_YearFnc.getCellData(1, "CAP_TOTAMT_2"));
    }
    //}

    //if(	dts_YearFnc.NameValue(1,"SALES_1") != "" || dts_YearFnc.NameValue(1,"BZ_PROFT_AMT_1") != "" || dts_YearFnc.NameValue(1,"NETINCM_AMT_1") != "" ||
    //	dts_YearFnc.NameValue(1,"ASST_TOTAMT_1") != "" || dts_YearFnc.NameValue(1,"DEBT_TOTAMT_1") != "" || dts_YearFnc.NameValue(1,"CAP_TOTAMT_1") != "" ) {
    dts_YearFncChange.insertRow();
