    fr_fn_list_sync();
};
scwin.fn_save = function() {
    if (!scwin.fn_checkForm()) return false;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '저장'))) return false;
    scwin.trsIdx = TR_JOB_INSERT;
    scwin.fn_getListPromtSeq();
    scwin.fn_trs();
};
scwin.fn_update = function() {
    if (!scwin.fn_checkForm()) return false;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '수정'))) return false;
    scwin.trsIdx = TR_JOB_UPDATE;
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '삭제'))) return false;
    scwin.trsIdx = TR_JOB_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    scwin.fn_setYearFncDataSet();
    scwin.fn_setInviewPrnDataSet();
    scwin.fn_setInviewDtlDataSet();
    scwin.fn_setInvstDataSet();
    trs_Save.Action = $c.lc.fn_encodeNSession("/ListPromtHistMgt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveListPromtPrfmKoList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_List, I:pInputITW=dts_IntviewDtlChange, I:pInputYF=dts_YearFncChange, I:pInputIPRN=dts_IntviewPrnChange, I:pInputInvst=dts_InvstChange, I:pFile=dts_fileList)";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",LIST_PROMT_SEQ=" + scwin.pLIST_PROMT_SEQ;
    trs_Save.Post();
};
scwin.fn_getListPromtSeq = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=LISTPRMTINTIWHISTKO_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=krx.lds.stf.lstmgt.listpromthistmgt.select.listpromtseq";
    dts_ListProMtSeq.DataID = encodeURI(url);
    dts_ListProMtSeq.reset();
    scwin.pLIST_PROMT_SEQ = dts_ListProMtSeq.getCellData(1, "LIST_PROMT_SEQ");
};
scwin.fn_excel = function() {
    if (dts_YearFncTotal.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_YearFncTotList, "연도별요약재무자료", "", "3");
    } else {
        $c.win.alert("저장되어 있는 데이터가  없습니다.");
    }
};


