        scwin.gIntviewOrder = 5;
    } else if (dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4") != '' && $c.ut.isDate(dts_IntviewDtlList.getCellData(1, "INTVIEW_DD_4"))) {
