        cnm: "cmb_INTVIEW_METHD_CD_2"
    }, {
        cid: "INTVIEW_METHD_CD",
        cnm: "cmb_INTVIEW_METHD_CD_3"
    }, {
        cid: "INTVIEW_METHD_CD",
        cnm: "cmb_INTVIEW_METHD_CD_4"
    }, {
        cid: "INTVIEW_METHD_CD",
        cnm: "cmb_INTVIEW_METHD_CD_5"
    }];
    var intviewMethd = "";
    for (i = 0; i < scwin.gIntviewOrder; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        if (objCod.getText() != "") {
            if (intviewMethd == "") intviewMethd = objCod.getText();

            else if (intviewMethd.indexOf(objCod.getText()) < 0) intviewMethd += ", " + objCod.getText();
        }
    }
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "INTVIEW_METHD_NM", intviewMethd);

    //주관회사
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "LEADCOM_NM", dts_List.getCellData(1, "LEADCOM_NM"));


    //체결시기 
    if (dts_List.getCellData(1, "MAJAGNT_COM_CONTRT_TRD_DD") != "") {
        dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "MAJAGNT_COM_CONTRT_TRD_DD", "‘" + dts_List.getCellData(1, "MAJAGNT_COM_CONTRT_TRD_DD").substr(2, 2) + "년");
    }

    //예정시기
    if (dts_IntviewDtlList.getCellData(1, "LIST_SCHDL_TM_" + scwin.gIntviewOrder) != "") {
        if (dts_IntviewDtlList.getCellData(1, "LIST_SCHDL_TM_" + scwin.gIntviewOrder) == "9999") dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "LIST_SCHDL_TM", eval("cmb_LIST_SCHDL_TM_" + scwin.gIntviewOrder).getText());

        else dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "LIST_SCHDL_TM", "‘" + dts_IntviewDtlList.getCellData(1, "LIST_SCHDL_TM_" + scwin.gIntviewOrder).substr(2, 2) + "년");
    }
    //상장교육
    var eduDd = "";
    if (dts_List.getCellData(1, "MNG_CRS_EDU_DD") != "") {
        eduDd = "경영자과정(‘" + dts_List.getCellData(1, "MNG_CRS_EDU_DD").substr(2, 2) + "년)";
        if (dts_List.getCellData(1, "PROFS_CRS_EDU_DD") != "") {
            eduDd += ", ";
            eduDd += " 전문가과정(‘" + dts_List.getCellData(1, "PROFS_CRS_EDU_DD").substr(2, 2) + "년)";
        }
    } else if (dts_List.getCellData(1, "MNG_CRS_EDU_DD") != "") eduDd = "전문가과정(‘" + dts_List.getCellData(1, "PROFS_CRS_EDU_DD").substr(2, 2) + "년)";
    dts_TplBody.setCellData(dts_TplBody.getRowPosition(), "CRS_EDU_NM", eduDd);

    //2. 상장관련

    //for( var i=1; i<= gIntviewOrder; i++ ) {
    //	if( dts_IntviewDtlList.NameValue(1, "MISC_INTVIEW_CONTN_" + i) != "" ) {
    //		txt2dts(dts_TplBlock1, dts_IntviewDtlList.NameValue(1, "MISC_INTVIEW_CONTN_" + i), "MISC_INTVIEW_CONTN" );
    //	} 
    //}
    scwin.txt2dts(dts_TplBlock1, dts_IntviewDtlList.getCellData(1, "MISC_INTVIEW_CONTN_" + MaxTab_01.getSelectedTabIndex()), "MISC_INTVIEW_CONTN");
    if (dts_TplBlock1.getTotalRow() == 0) dts_TplBlock1.insertRow();
};
scwin.txt2dts = function(d, t, nameString) {
    t = $c.ut.replaceAll(t, '&', '&amp;');
    t = $c.ut.replaceAll(t, '<', '&lt;');
    t = $c.ut.replaceAll(t, '>', '&gt;');
    var arrStr = t.split("\n");
    for (var i = 0; i < arrStr.length; i++) {
        d.AddRow();
        if (arrStr[i].charCodeAt(arrStr[i].length - 1) == 13) {
            d.setCellData(d.getTotalRow(), getCellData, arrStr[i].substring(0, arrStr[i].length - 1));
        } else {
            d.setCellData(d.getTotalRow(), getCellData, arrStr[i]);
        }
    }
};
