scwin.dts_financeInfo_OnLoadCompleted = function(rowcount) {
    var YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    var YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    var YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    for (var i = 1; i <= rowcount; i++) {
        if (YY_3 == dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
            $c.stf.setObjectValue(edt_SALES_2, dts_financeInfo.getCellData(i, "SALES"));
            $c.stf.setObjectValue(edt_BZ_PROFT_AMT_2, dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
            $c.stf.setObjectValue(edt_NETINCM_AMT_2, dts_financeInfo.getCellData(i, "NETINCM_AMT"));
            $c.stf.setObjectValue(edt_ASST_TOTAMT_2, dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
            $c.stf.setObjectValue(edt_DEBT_TOTAMT_2, dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
            $c.stf.setObjectValue(edt_CAP_TOTAMT_2, dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
        } else if (YY_2 == dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
            $c.stf.setObjectValue(edt_SALES_1, dts_financeInfo.getCellData(i, "SALES"));
            $c.stf.setObjectValue(edt_BZ_PROFT_AMT_1, dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
            $c.stf.setObjectValue(edt_NETINCM_AMT_1, dts_financeInfo.getCellData(i, "NETINCM_AMT"));
            $c.stf.setObjectValue(edt_ASST_TOTAMT_1, dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
            $c.stf.setObjectValue(edt_DEBT_TOTAMT_1, dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
            $c.stf.setObjectValue(edt_CAP_TOTAMT_1, dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
        } else if (YY_1 == dts_financeInfo.getCellData(i, "FISCAL_YYYY")) {
            $c.stf.setObjectValue(edt_SALES_0, dts_financeInfo.getCellData(i, "SALES"));
            $c.stf.setObjectValue(edt_BZ_PROFT_AMT_0, dts_financeInfo.getCellData(i, "BZ_PROFT_AMT"));
            $c.stf.setObjectValue(edt_NETINCM_AMT_0, dts_financeInfo.getCellData(i, "NETINCM_AMT"));
            $c.stf.setObjectValue(edt_ASST_TOTAMT_0, dts_financeInfo.getCellData(i, "ASST_TOTAMT"));
            $c.stf.setObjectValue(edt_DEBT_TOTAMT_0, dts_financeInfo.getCellData(i, "DEBT_TOTAMT"));
            $c.stf.setObjectValue(edt_CAP_TOTAMT_0, dts_financeInfo.getCellData(i, "CAP_TOTAMT"));
        }
    }
};
