scwin.chk_FORN_COM_YN_onclick = function() {
    if (scwin.pLIST_PROMT_SEQ == "" && dts_List.getCellData(1, "FORN_COM_YN") == "1") {
        scwin.fn_set_regNo();
    }
};
scwin.btn_report_onclick = function() {
    scwin.fn_report();
};
scwin.gform_onload = function() {
    scwin.fn_init();
    $c.elw.fn_searchCode();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    scwin.fn_list_sync();
    if (scwin.pLIST_PROMT_SEQ == "" || dts_List.getCellData(1, "FORN_COM_YN") == "") chk_FORN_COM_YN.setValue(0);
};
